/* Download statistics for the demo corpus.
 *
 * Generated by scripts/downloads/05-build.mjs. Lifetime installs are real
 * public figures from the Google Play install bracket; the weekly series and
 * rate are modelled, because neither store publishes download history.
 * Every record carries `confidence: 'estimated'` on purpose.
 */

import raw from './downloads.json';

export type DownloadSource = 'play' | 'appstore' | 'estimate';
export type InstallConfidence = 'bracket' | 'estimated';

export interface DownloadPoint {
	/** ISO date, start of the week */
	date: string;
	downloads: number;
}

export interface DownloadStats {
	id: string;
	name: string;
	categoryId: string;
	platform: string;
	/** modelled lifetime installs */
	installs: number;
	/** published Play bracket, when available */
	installsLow: number | null;
	installsHigh: number | null;
	installsLabel: string | null;
	iosRatings: number | null;
	androidRatings: number | null;
	iosAverage: number | null;
	androidAverage: number | null;
	ageDays: number;
	recentShare: number;
	/** modelled trailing average, downloads per day */
	ratePerDay: number;
	/** modelled change vs the previous 4 weeks, as a fraction (0.08 = +8%) */
	rateDelta: number;
	source: DownloadSource;
	installsConfidence: InstallConfidence;
	confidence: 'estimated';
	asOf: string;
	weekly: DownloadPoint[];
	/** seeded demand shocks used by the demo chart/correlation story */
	events?: { week: number; kind: 'dip' | 'spike'; factor: number }[];
	provenance: {
		playAppId: string | null;
		playTitle: string | null;
		playDeveloper: string | null;
		playUrl: string | null;
		iosTrackId: number | null;
		iosTitle: string | null;
		iosDeveloper: string | null;
	};
	notes?: string;
}

export interface DownloadMeta {
	asOf: string;
	generatedAt: string;
	appCount: number;
	country: string;
	method: string;
	sources: { id: string; name: string; url: string }[];
	confidence: 'estimated';
}

const dataset = raw as unknown as {
	meta: DownloadMeta;
	categories: Record<string, { id: string; apps: number; installs: number; ratePerDay: number }>;
	apps: Record<string, DownloadStats>;
};

export const downloadMeta = dataset.meta;
export const downloadCategories = dataset.categories;

export function downloadStats(appId: string): DownloadStats | undefined {
	return dataset.apps[appId];
}

/** Latest weekly downloads for an app, or 0 when unknown. */
export function weeklyDownloads(appId: string): number {
	const stats = downloadStats(appId);
	return stats?.weekly.at(-1)?.downloads ?? 0;
}
